/// FizzBuzz for 1..n: Fizz, Buzz, FizzBuzz or the number as text.
pub fn fizzbuzz(n: Int) -> List[Str] {
  var out: List[Str] = []
  for i in range(1, n + 1) {
    let s = match i % 15 == 0 {
      true => "FizzBuzz",
      false => match i % 3 == 0 {
        true => "Fizz",
        false => match i % 5 == 0 {
          true => "Buzz",
          false => i.to_str(),
        },
      },
    }
    out = out.push(s)
  }
  return out
}
